-- Stored form: NFKC, combining marks and apostrophes dropped, "&" -> " and ", locale-free lower
-- case, every Latin letter kept, anything else except 0-9 . , -> one space.
create or replace function atlas_private.product_text_fold(p_value text)
returns text
language plpgsql
immutable
parallel safe
set search_path = ''
as $function$
declare
  c constant jsonb := atlas_private.product_identity_constants();
  s text;
begin
  if p_value is null then return ''; end if;
  s := pg_catalog.normalize(p_value, 'NFKC');
  s := pg_catalog.translate(s, c->>'fold_drop', '');
  s := pg_catalog.regexp_replace(s, E'[̀-ͯ]+', '', 'g');
  s := pg_catalog.replace(pg_catalog.replace(s, '&', ' and '), '×', ' x ');
  s := pg_catalog.translate(s, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz');
  s := pg_catalog.translate(s, c->>'case_upper', c->>'case_lower');
  s := pg_catalog.regexp_replace(s, '[^a-z0-9.,' || (c->>'keep_letters') || ']+', ' ', 'g');
  return pg_catalog.btrim(s, ' ');
end
$function$;

-- Search-only form: accents removed, þ -> th, ð -> d, æ -> ae. Never stored
-- on an item or alias row.
create or replace function atlas_private.product_search_fold(p_value text)
returns text
language plpgsql
immutable
parallel safe
set search_path = ''
as $function$
declare
  c constant jsonb := atlas_private.product_identity_constants();
  s text := atlas_private.product_text_fold(p_value);
  letter text;
begin
  for letter in select pg_catalog.jsonb_object_keys(c->'search_multi') loop
    s := pg_catalog.replace(s, letter, c->'search_multi'->>letter);
  end loop;
  return pg_catalog.translate(s, c->>'search_from', c->>'search_to');
end
$function$;

-- "1,000" is ambiguous (the S86.1 rule); "1,5" and "1.5" are 1.5.
create or replace function atlas_private.product_parse_decimal(p_text text)
returns jsonb
language plpgsql
immutable
parallel safe
set search_path = ''
as $function$
declare
  m text[];
begin
  m := pg_catalog.regexp_match(coalesce(p_text, ''), '^([0-9]+)(?:([.,])([0-9]+))?$');
  if m is null then return jsonb_build_object('value', null, 'ambiguous', false); end if;
  if m[2] = ',' and pg_catalog.char_length(m[3]) = 3 and m[1] <> '0' then
    return jsonb_build_object('value', null, 'ambiguous', true);
  end if;
  return jsonb_build_object('value', (m[1] || coalesce('.' || m[3], ''))::numeric, 'ambiguous', false);
end
$function$;

create or replace function atlas_private.product_format_quantity(p_value numeric)
returns text
language sql
immutable
parallel safe
set search_path = ''
as $function$
  select pg_catalog.trim_scale(pg_catalog.round(p_value, 3))::text;
$function$;

-- [base, factor] for a unit word, or null.
create or replace function atlas_private.product_unit_for(p_word text)
returns jsonb
language sql
immutable
parallel safe
set search_path = ''
as $function$
  select case
    when (atlas_private.product_identity_constants()->'measure_units') ? p_word
      then atlas_private.product_identity_constants()->'measure_units'->p_word
    when (atlas_private.product_identity_constants()->'count_units') ? p_word
      then '["count", 1]'::jsonb
  end;
$function$;

create or replace function atlas_private.product_empty_package(p_kind text, p_pack_text text, p_reason text)
returns jsonb
language sql
immutable
parallel safe
set search_path = ''
as $function$
  select jsonb_build_object('kind', p_kind, 'unit_quantity', null, 'unit_base', null,
    'units_per_pack', null, 'pack_text', p_pack_text, 'ambiguous_reason', p_reason);
$function$;

-- First pack expression in free text (parsePackageText).
create or replace function atlas_private.product_parse_package(p_text text)
returns jsonb
language plpgsql
immutable
parallel safe
set search_path = ''
as $function$
declare
  c constant jsonb := atlas_private.product_identity_constants();
  folded text := atlas_private.product_text_fold(p_text);
  m text[];
  amount jsonb;
  unit_info jsonb;
  units numeric;
begin
  if folded = '' then return atlas_private.product_empty_package('none', null, null); end if;
  m := pg_catalog.regexp_match(folded, '(' || (c->'pack_patterns'->>'multipack') || ')');
  if m is not null then
    units := m[2]::numeric;
    amount := atlas_private.product_parse_decimal(m[3]);
    unit_info := atlas_private.product_unit_for(m[4]);
    if (amount->>'ambiguous')::boolean then
      return atlas_private.product_empty_package('ambiguous', pg_catalog.btrim(m[1], ' '), 'decimal_comma_or_thousands');
    end if;
    if units > 0 and (amount->>'value')::numeric > 0 then
      return jsonb_build_object(
        'kind', 'multipack',
        'unit_quantity', pg_catalog.trim_scale(pg_catalog.round((amount->>'value')::numeric * (unit_info->>1)::numeric, 3)),
        'unit_base', unit_info->>0,
        'units_per_pack', units,
        'pack_text', pg_catalog.btrim(m[1], ' '),
        'ambiguous_reason', null);
    end if;
  end if;
  m := pg_catalog.regexp_match(folded, '(' || (c->'pack_patterns'->>'measure') || ')');
  if m is null then
    m := pg_catalog.regexp_match(folded, '(' || (c->'pack_patterns'->>'count') || ')');
  end if;
  if m is null then return atlas_private.product_empty_package('none', null, null); end if;
  amount := atlas_private.product_parse_decimal(m[2]);
  if (amount->>'ambiguous')::boolean then
    return atlas_private.product_empty_package('ambiguous', pg_catalog.btrim(m[1], ' '), 'decimal_comma_or_thousands');
  end if;
  if coalesce((amount->>'value')::numeric, 0) <= 0 then
    return atlas_private.product_empty_package('none', null, null);
  end if;
  unit_info := atlas_private.product_unit_for(m[3]);
  return jsonb_build_object(
    'kind', case when unit_info->>0 = 'count' then 'count' else 'single' end,
    'unit_quantity', pg_catalog.trim_scale(pg_catalog.round((amount->>'value')::numeric * (unit_info->>1)::numeric, 3)),
    'unit_base', unit_info->>0,
    'units_per_pack', null,
    'pack_text', pg_catalog.btrim(m[1], ' '),
    'ambiguous_reason', null);
end
$function$;

-- Structured pack of an item or draft (parsePackage). Read-only.
create or replace function atlas_private.product_parse_item_package(
  p_unit_size_quantity numeric,
  p_unit_size_base text,
  p_size_ml numeric,
  p_package_weight_g numeric,
  p_package_size text,
  p_name text,
  p_unit text
)
returns jsonb
language plpgsql
immutable
parallel safe
set search_path = ''
as $function$
declare
  c constant jsonb := atlas_private.product_identity_constants();
  from_text jsonb := atlas_private.product_parse_package(p_package_size);
  from_name jsonb := atlas_private.product_parse_package(p_name);
  case_row boolean := (c->'case_units') ? atlas_private.product_search_fold(p_unit);
  quantity numeric;
  base text;
  source text;
  units numeric;
  reason text;
begin
  if p_unit_size_quantity > 0 and p_unit_size_base in ('ml', 'g', 'count') then
    quantity := p_unit_size_quantity; base := p_unit_size_base; source := 'unit_size';
  elsif p_size_ml > 0 then
    quantity := p_size_ml; base := 'ml'; source := 'size_ml';
  elsif p_package_weight_g > 0 then
    quantity := p_package_weight_g; base := 'g'; source := 'package_weight_g';
  elsif from_text->>'unit_quantity' is not null then
    quantity := (from_text->>'unit_quantity')::numeric; base := from_text->>'unit_base'; source := 'package_size';
  elsif from_name->>'unit_quantity' is not null then
    quantity := (from_name->>'unit_quantity')::numeric; base := from_name->>'unit_base'; source := 'name';
  end if;

  if quantity is null then
    reason := case when from_text->>'kind' = 'ambiguous' then from_text->>'ambiguous_reason'
                   when from_name->>'kind' = 'ambiguous' then from_name->>'ambiguous_reason' end;
    return atlas_private.product_empty_package(case when reason is null then 'none' else 'ambiguous' end, null, reason)
      || jsonb_build_object('source', null);
  end if;
  if case_row then
    if from_text->>'kind' = 'multipack' then units := (from_text->>'units_per_pack')::numeric;
    elsif from_name->>'kind' = 'multipack' then units := (from_name->>'units_per_pack')::numeric;
    end if;
  end if;
  return jsonb_build_object(
    'kind', case when units is not null then 'multipack' when base = 'count' then 'count' else 'single' end,
    'unit_quantity', pg_catalog.trim_scale(pg_catalog.round(quantity, 3)),
    'unit_base', base,
    'units_per_pack', units,
    'pack_text', coalesce(from_text->>'pack_text', from_name->>'pack_text'),
    'ambiguous_reason', null,
    'source', source);
end
$function$;

-- "1000ml", "6x1000ml", "1250count" or "?".
create or replace function atlas_private.product_pack_key(
  p_unit_size_quantity numeric,
  p_unit_size_base text,
  p_size_ml numeric,
  p_package_weight_g numeric,
  p_package_size text,
  p_name text,
  p_unit text
)
returns text
language plpgsql
immutable
parallel safe
set search_path = ''
as $function$
declare
  pack jsonb := atlas_private.product_parse_item_package(
    p_unit_size_quantity, p_unit_size_base, p_size_ml, p_package_weight_g, p_package_size, p_name, p_unit);
  inner_key text;
begin
  if pack->>'unit_quantity' is null then return '?'; end if;
  inner_key := atlas_private.product_format_quantity((pack->>'unit_quantity')::numeric) || (pack->>'unit_base');
  if pack->>'units_per_pack' is not null then
    return atlas_private.product_format_quantity((pack->>'units_per_pack')::numeric) || 'x' || inner_key;
  end if;
  return inner_key;
end
$function$;

-- Stored-form tokens in reading order (nameTokens).
create or replace function atlas_private.product_name_tokens(p_value text)
returns text[]
language plpgsql
immutable
parallel safe
set search_path = ''
as $function$
declare
  c constant jsonb := atlas_private.product_identity_constants();
  folded text := atlas_private.product_text_fold(p_value);
  strip_pattern text;
  token text;
  cleaned text;
  searched text;
  result text[] := '{}';
begin
  if folded = '' then return result; end if;
  strip_pattern := (c->'pack_patterns'->>'multipack') || '|' || (c->'pack_patterns'->>'measure')
    || '|' || (c->'pack_patterns'->>'count');
  foreach token in array pg_catalog.string_to_array(pg_catalog.regexp_replace(folded, strip_pattern, ' ', 'g'), ' ') loop
    cleaned := pg_catalog.regexp_replace(token, '^[.,]+|[.,]+$', '', 'g');
    if cleaned = '' then continue; end if;
    searched := atlas_private.product_search_fold(cleaned);
    if (c->'lexicon'->'stop') ? searched or (c->'lexicon'->'packaging') ? searched then continue; end if;
    result := result || cleaned;
  end loop;
  return result;
end
$function$;

-- Search-only tokens: search-folded name tokens with lexicon synonyms.
create or replace function atlas_private.product_match_tokens(p_value text)
returns text[]
language plpgsql
immutable
parallel safe
set search_path = ''
as $function$
declare
  c constant jsonb := atlas_private.product_identity_constants();
  raw text[];
  mapped text[] := '{}';
  result text[] := '{}';
  idx integer := 1;
  total integer;
  span integer;
  phrase text;
  matched boolean;
  token text;
begin
  select coalesce(array_agg(atlas_private.product_search_fold(t) order by ordinality), '{}')
  into raw
  from unnest(atlas_private.product_name_tokens(p_value)) with ordinality as u(t, ordinality);
  total := coalesce(pg_catalog.array_length(raw, 1), 0);
  while idx <= total loop
    matched := false;
    foreach span in array array[3, 2] loop
      if idx + span - 1 > total then continue; end if;
      phrase := pg_catalog.array_to_string(raw[idx:idx + span - 1], ' ');
      if (c->'lexicon'->'phrases') ? phrase then
        mapped := mapped || pg_catalog.string_to_array(c->'lexicon'->'phrases'->>phrase, ' ');
        idx := idx + span;
        matched := true;
        exit;
      end if;
    end loop;
    if matched then continue; end if;
    mapped := mapped || pg_catalog.string_to_array(coalesce(c->'lexicon'->'tokens'->>raw[idx], raw[idx]), ' ');
    idx := idx + 1;
  end loop;
  foreach token in array mapped loop
    if token = '' or (c->'lexicon'->'stop') ? token or (c->'lexicon'->'packaging') ? token then continue; end if;
    result := result || token;
  end loop;
  return result;
end
$function$;

create or replace function atlas_private.product_sorted_key(p_tokens text[])
returns text
language sql
immutable
parallel safe
set search_path = ''
as $function$
  select nullif(coalesce(pg_catalog.string_agg(t, ' ' order by t), ''), '')
  from (select distinct u.t collate "C" as t from unnest(p_tokens) as u(t) where u.t <> '') tokens;
$function$;

-- Stored identity name key (keeps every letter).
create or replace function atlas_private.product_name_key(
  p_brand text, p_product_name text, p_variant text, p_name text)
returns text
language sql
immutable
parallel safe
set search_path = ''
as $function$
  select atlas_private.product_sorted_key(
    atlas_private.product_name_tokens(p_brand)
    || atlas_private.product_name_tokens(
         case when atlas_private.product_text_fold(p_product_name) <> '' then p_product_name else p_name end)
    || atlas_private.product_name_tokens(p_variant));
$function$;

-- Search-only match key (accent-insensitive, lexicon-mapped).
create or replace function atlas_private.product_match_key(
  p_brand text, p_product_name text, p_variant text, p_name text)
returns text
language sql
immutable
parallel safe
set search_path = ''
as $function$
  select atlas_private.product_sorted_key(
    atlas_private.product_match_tokens(p_brand)
    || atlas_private.product_match_tokens(
         case when atlas_private.product_text_fold(p_product_name) <> '' then p_product_name else p_name end)
    || atlas_private.product_match_tokens(p_variant));
$function$;

create or replace function atlas_private.product_identity_key(
  p_brand text, p_product_name text, p_variant text, p_name text,
  p_unit_size_quantity numeric, p_unit_size_base text, p_size_ml numeric,
  p_package_weight_g numeric, p_package_size text, p_unit text)
returns text
language sql
immutable
parallel safe
set search_path = ''
as $function$
  select case when k.name_key is null then null
    else k.name_key || '|' || atlas_private.product_pack_key(
      p_unit_size_quantity, p_unit_size_base, p_size_ml, p_package_weight_g, p_package_size, p_name, p_unit) end
  from (select atlas_private.product_name_key(p_brand, p_product_name, p_variant, p_name) as name_key) k;
$function$;

create or replace function atlas_private.product_gtin_valid(p_digits text)
returns boolean
language plpgsql
immutable
parallel safe
set search_path = ''
as $function$
declare
  body text;
  total integer := 0;
  i integer;
begin
  if p_digits is null or p_digits !~ '^[0-9]+$' or pg_catalog.char_length(p_digits) not in (8, 12, 13, 14) then
    return false;
  end if;
  body := pg_catalog.left(p_digits, -1);
  for i in 0 .. pg_catalog.char_length(body) - 1 loop
    total := total + pg_catalog.substr(body, pg_catalog.char_length(body) - i, 1)::integer
      * case when i % 2 = 0 then 3 else 1 end;
  end loop;
  return (10 - (total % 10)) % 10 = pg_catalog.right(p_digits, 1)::integer;
end
$function$;

create or replace function atlas_private.product_upce_expand(p_code text)
returns text
language plpgsql
immutable
parallel safe
set search_path = ''
as $function$
declare
  d text;
  last_digit text;
  body text;
begin
  if p_code is null or p_code !~ '^[01][0-9]{7}$' then return null; end if;
  d := pg_catalog.substr(p_code, 2, 6);
  last_digit := pg_catalog.substr(d, 6, 1);
  if last_digit in ('0', '1', '2') then
    body := pg_catalog.substr(d, 1, 2) || last_digit || '0000' || pg_catalog.substr(d, 3, 3);
  elsif last_digit = '3' then
    body := pg_catalog.substr(d, 1, 3) || '00000' || pg_catalog.substr(d, 4, 2);
  elsif last_digit = '4' then
    body := pg_catalog.substr(d, 1, 4) || '00000' || pg_catalog.substr(d, 5, 1);
  else
    body := pg_catalog.substr(d, 1, 5) || '0000' || last_digit;
  end if;
  return pg_catalog.substr(p_code, 1, 1) || body || pg_catalog.substr(p_code, 8, 1);
end
$function$;

create or replace function atlas_private.product_symbology_normalize(p_value text)
returns text
language sql
immutable
parallel safe
set search_path = ''
as $function$
  select coalesce(nullif(pg_catalog.left(pg_catalog.btrim(pg_catalog.regexp_replace(pg_catalog.regexp_replace(
    pg_catalog.translate(coalesce(p_value, ''), 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz'),
    E'[ \t\n\r -]+', '_', 'g'), '[^a-z0-9_]', '', 'g'), '_'), 64), ''), 'unknown');
$function$;

-- normalizeCode twin: {kind, normalized, valid, symbology, reason}.
create or replace function atlas_private.product_code_normalize(p_kind text, p_raw text, p_symbology text default null)
returns jsonb
language plpgsql
immutable
parallel safe
set search_path = ''
as $function$
declare
  requested text := case when p_kind in ('gtin', 'sku', 'supplier_ref', 'internal', 'other_barcode') then p_kind end;
  symbology text := atlas_private.product_symbology_normalize(p_symbology);
  compact text := pg_catalog.translate(coalesce(p_raw, ''), E' \t\n\r ', '');
  digits text;
  candidate text;
  normalized text;
begin
  if compact = '' then
    return jsonb_build_object('kind', coalesce(requested, 'other_barcode'), 'normalized', null, 'valid', false,
      'symbology', symbology, 'reason', 'empty');
  end if;
  digits := pg_catalog.replace(compact, '-', '');
  if (requested is null or requested = 'gtin') and digits ~ '^[0-9]+$' then
    candidate := digits;
    if symbology = 'upc_e' and pg_catalog.char_length(digits) = 8 then
      candidate := coalesce(atlas_private.product_upce_expand(digits), digits);
    end if;
    if pg_catalog.char_length(candidate) in (8, 12, 13, 14) then
      if atlas_private.product_gtin_valid(candidate) then
        return jsonb_build_object('kind', 'gtin', 'normalized', pg_catalog.lpad(candidate, 14, '0'), 'valid', true,
          'symbology', symbology, 'reason', null);
      end if;
      return jsonb_build_object('kind', 'gtin', 'normalized', null, 'valid', false, 'symbology', symbology, 'reason', 'check_digit');
    end if;
    if requested = 'gtin' then
      return jsonb_build_object('kind', 'gtin', 'normalized', null, 'valid', false, 'symbology', symbology, 'reason', 'length');
    end if;
  elsif requested = 'gtin' then
    return jsonb_build_object('kind', 'gtin', 'normalized', null, 'valid', false, 'symbology', symbology, 'reason', 'not_numeric');
  end if;
  normalized := pg_catalog.translate(compact, 'abcdefghijklmnopqrstuvwxyz', 'ABCDEFGHIJKLMNOPQRSTUVWXYZ');
  if pg_catalog.char_length(normalized) not between 3 and 128 then
    return jsonb_build_object('kind', coalesce(requested, 'other_barcode'), 'normalized', null, 'valid', false,
      'symbology', symbology, 'reason', 'length');
  end if;
  return jsonb_build_object('kind', coalesce(requested, 'other_barcode'), 'normalized', normalized, 'valid', true,
    'symbology', symbology, 'reason', null);
end
$function$;

create or replace function atlas_private.product_pack_from_key(p_key text)
returns jsonb
language plpgsql
immutable
parallel safe
set search_path = ''
as $function$
declare
  m text[] := pg_catalog.regexp_match(coalesce(p_key, ''), '^(?:([0-9.]+)x)?([0-9.]+)(ml|g|count)$');
begin
  if m is null then return null; end if;
  return jsonb_build_object('units_per_pack', m[1]::numeric, 'unit_quantity', m[2]::numeric, 'unit_base', m[3]);
end
$function$;

create or replace function atlas_private.product_variant_tokens(p_tokens text[])
returns text[]
language sql
immutable
parallel safe
set search_path = ''
as $function$
  select coalesce(array_agg(distinct t collate "C" order by t collate "C"), '{}')
  from unnest(p_tokens) as u(t)
  where (atlas_private.product_identity_constants()->'lexicon'->'variants') ? t;
$function$;

create or replace function atlas_private.product_dice(p_left text[], p_right text[])
returns numeric
language sql
immutable
parallel safe
set search_path = ''
as $function$
  select case
    when coalesce(pg_catalog.cardinality(p_left), 0) = 0 or coalesce(pg_catalog.cardinality(p_right), 0) = 0 then 0::numeric
    else (2 * (select count(*) from (select distinct l from unnest(p_left) l where l = any(p_right)) shared))::numeric
      / ((select count(distinct l) from unnest(p_left) l) + (select count(distinct r) from unnest(p_right) r))
  end;
$function$;

-- duplicateScore twin. Draft and item are the duplicateKeys() shape:
-- {name_key, match_key, pack_key, brand_key, item_class, legacy_key,
--  codes: [{kind, normalized, supplier_id}], alias_keys: [...]}.
create or replace function atlas_private.catalog_duplicate_score(p_draft jsonb, p_item jsonb)
returns jsonb
language plpgsql
immutable
parallel safe
set search_path = ''
as $function$
declare
  evidence jsonb := '[]'::jsonb;
  caps integer[] := '{}';
  points integer;
  best numeric;
  alias_key text;
  draft_tokens text[] := coalesce(pg_catalog.string_to_array(nullif(p_draft->>'match_key', ''), ' '), '{}');
  item_tokens text[] := coalesce(pg_catalog.string_to_array(nullif(p_item->>'match_key', ''), ' '), '{}');
  item_aliases text[] := coalesce((select array_agg(a) from jsonb_array_elements_text(coalesce(p_item->'alias_keys', '[]')) a where a <> ''), '{}');
  draft_aliases text[] := coalesce((select array_agg(a) from jsonb_array_elements_text(coalesce(p_draft->'alias_keys', '[]')) a where a <> ''), '{}');
  identity_exact boolean;
  draft_pack jsonb := atlas_private.product_pack_from_key(p_draft->>'pack_key');
  item_pack jsonb := atlas_private.product_pack_from_key(p_item->>'pack_key');
  pack_state text := 'unknown';
  larger numeric;
  draft_variants text[];
  item_variants text[];
  capped integer;
begin
  if exists (
    select 1
    from jsonb_array_elements(coalesce(p_draft->'codes', '[]')) d
    join jsonb_array_elements(coalesce(p_item->'codes', '[]')) i
      on d->>'kind' = i->>'kind' and d->>'normalized' = i->>'normalized'
    where nullif(d->>'normalized', '') is not null
      and (d->>'kind' <> 'supplier_ref' or nullif(d->>'supplier_id', '') is null
           or nullif(i->>'supplier_id', '') is null or d->>'supplier_id' = i->>'supplier_id')
  ) then
    return jsonb_build_object('score', 1, 'points', 100, 'caps', '[]'::jsonb, 'code_collision', true,
      'evidence', jsonb_build_array(jsonb_build_object('signal', 'code', 'polarity', 'for',
        'text', 'Same barcode, SKU or supplier reference')));
  end if;

  identity_exact := nullif(p_draft->>'name_key', '') is not null and p_draft->>'name_key' = p_item->>'name_key'
    and nullif(p_draft->>'pack_key', '') is not null and p_draft->>'pack_key' <> '?' and p_draft->>'pack_key' = p_item->>'pack_key';
  if identity_exact then
    points := 99;
    evidence := evidence || jsonb_build_object('signal', 'identity_key', 'polarity', 'for', 'text', 'Same name and package');
  elsif nullif(p_draft->>'name_key', '') is not null and p_draft->>'name_key' = p_item->>'name_key' then
    points := 90;
    evidence := evidence || jsonb_build_object('signal', 'name_key', 'polarity', 'for', 'text', 'Same name');
  elsif nullif(p_draft->>'match_key', '') is not null and p_draft->>'match_key' = p_item->>'match_key' then
    points := 90;
    evidence := evidence || jsonb_build_object('signal', 'match_key', 'polarity', 'for', 'text', 'Same name in another spelling or language');
  elsif (nullif(p_draft->>'match_key', '') is not null and p_draft->>'match_key' = any(item_aliases))
     or (nullif(p_item->>'match_key', '') is not null and p_item->>'match_key' = any(draft_aliases)) then
    points := 90;
    evidence := evidence || jsonb_build_object('signal', 'alias', 'polarity', 'for', 'text', 'Matches an alias of this item');
  elsif nullif(p_draft->>'match_key', '') is not null and p_draft->>'match_key' = p_item->>'legacy_key' then
    points := 80;
    evidence := evidence || jsonb_build_object('signal', 'legacy_key', 'polarity', 'for', 'text', 'Matches this item''s canonical key');
  else
    best := atlas_private.product_dice(draft_tokens, item_tokens);
    foreach alias_key in array item_aliases loop
      best := greatest(best, atlas_private.product_dice(draft_tokens, pg_catalog.string_to_array(alias_key, ' ')));
    end loop;
    points := pg_catalog.round(80 * best)::integer;
    if best > 0 then
      evidence := evidence || jsonb_build_object('signal', 'tokens', 'polarity', 'for',
        'text', pg_catalog.round(best * 100)::integer || '% of the name words agree');
    end if;
  end if;

  if draft_pack is not null and item_pack is not null then
    larger := greatest((draft_pack->>'unit_quantity')::numeric, (item_pack->>'unit_quantity')::numeric);
    if draft_pack->>'unit_base' <> item_pack->>'unit_base'
       or abs((draft_pack->>'unit_quantity')::numeric - (item_pack->>'unit_quantity')::numeric) > larger * 0.02 then
      pack_state := 'size_conflict';
    elsif coalesce((draft_pack->>'units_per_pack')::numeric, 1) <> coalesce((item_pack->>'units_per_pack')::numeric, 1) then
      pack_state := 'case_vs_unit';
    else
      pack_state := 'same';
    end if;
  end if;
  if pack_state = 'same' and not identity_exact then
    points := points + 10;
    evidence := evidence || jsonb_build_object('signal', 'pack', 'polarity', 'for', 'text', 'Same package size');
  elsif pack_state = 'size_conflict' then
    caps := caps || 55;
    evidence := evidence || jsonb_build_object('signal', 'pack', 'polarity', 'against', 'text', 'Different package size');
  elsif pack_state = 'case_vs_unit' then
    caps := caps || 70;
    evidence := evidence || jsonb_build_object('signal', 'pack', 'polarity', 'against', 'text', 'Case and single unit');
  end if;

  if nullif(p_draft->>'brand_key', '') is not null and nullif(p_item->>'brand_key', '') is not null then
    if p_draft->>'brand_key' = p_item->>'brand_key' then
      points := points + 10;
      evidence := evidence || jsonb_build_object('signal', 'brand', 'polarity', 'for', 'text', 'Same brand');
    else
      caps := caps || 40;
      evidence := evidence || jsonb_build_object('signal', 'brand', 'polarity', 'against', 'text', 'Different brand');
    end if;
  end if;

  draft_variants := atlas_private.product_variant_tokens(draft_tokens);
  item_variants := atlas_private.product_variant_tokens(item_tokens);
  if pg_catalog.cardinality(draft_variants) > 0 and pg_catalog.cardinality(item_variants) > 0
     and draft_variants <> item_variants then
    caps := caps || 35;
    evidence := evidence || jsonb_build_object('signal', 'variant', 'polarity', 'against', 'text', 'Different flavour or variant');
  end if;
  if nullif(p_draft->>'item_class', '') is not null and nullif(p_item->>'item_class', '') is not null
     and p_draft->>'item_class' <> p_item->>'item_class' then
    caps := caps || 45;
    evidence := evidence || jsonb_build_object('signal', 'class', 'polarity', 'against', 'text', 'Different product type');
  end if;

  capped := greatest(0, least(points, 99, coalesce((select min(x) from unnest(caps) x), 99)));
  return jsonb_build_object('score', pg_catalog.round(capped::numeric / 100, 2), 'points', points,
    'caps', to_jsonb(caps), 'evidence', evidence, 'code_collision', false);
end
$function$;

-- duplicateKeys twin: the keys of a draft (values as submitted).
create or replace function atlas_private.catalog_duplicate_keys(p_values jsonb)
returns jsonb
language plpgsql
immutable
set search_path = ''
as $function$
declare
  v jsonb := coalesce(p_values, '{}'::jsonb);
  code_keys jsonb;
  alias_keys jsonb;
begin
  select coalesce(jsonb_agg(n.code || jsonb_build_object('supplier_id', nullif(c->>'supplier_id', ''))
                            order by ord), '[]'::jsonb)
  into code_keys
  from jsonb_array_elements(case when jsonb_typeof(v->'codes') = 'array' then v->'codes' else '[]'::jsonb end)
       with ordinality as e(c, ord)
  cross join lateral (select atlas_private.product_code_normalize(c->>'kind',
    coalesce(c->>'code', c->>'normalized', c->>'raw'), c->>'symbology') as code) n
  where (n.code->>'valid')::boolean;

  select coalesce(jsonb_agg(k.key order by ord), '[]'::jsonb)
  into alias_keys
  from jsonb_array_elements(case when jsonb_typeof(v->'aliases') = 'array' then v->'aliases' else '[]'::jsonb end)
       with ordinality as e(a, ord)
  cross join lateral (select atlas_private.product_match_key(null, null, null,
    case when jsonb_typeof(a) = 'string' then a #>> '{}' else a->>'alias' end) as key) k
  where k.key is not null;

  return jsonb_build_object(
    'name_key', atlas_private.product_name_key(v->>'brand', v->>'product_name', v->>'variant', v->>'name'),
    'match_key', atlas_private.product_match_key(v->>'brand', v->>'product_name', v->>'variant', v->>'name'),
    'pack_key', atlas_private.product_pack_key(nullif(v->>'unit_size_quantity', '')::numeric, v->>'unit_size_base',
      nullif(v->>'size_ml', '')::numeric, nullif(v->>'package_weight_g', '')::numeric, v->>'package_size',
      v->>'name', v->>'unit'),
    'brand_key', atlas_private.product_match_key(null, null, null, v->>'brand'),
    'item_class', nullif(v->>'item_class', ''),
    'legacy_key', case when coalesce(v->>'canonical_key', '') <> '' then atlas_private.product_match_key(null, null, null,
      pg_catalog.regexp_replace(v->>'canonical_key', '[-_:]+', ' ', 'g')) end,
    'codes', code_keys,
    'alias_keys', alias_keys);
end
$function$;

-- ---------------------------------------------------------------------------
-- 2. Item attributes (empty; filled only through approved requests) and the
--    taxonomy reference table
-- ---------------------------------------------------------------------------
alter table public.inventory_items
  add column if not exists product_name text,
  add column if not exists variant text,
  add column if not exists item_class text,
  add column if not exists packaging_type text,
  add column if not exists unit_size_quantity numeric,
  add column if not exists unit_size_base text,
  add column if not exists abv_percent numeric,
  add column if not exists attributes_source jsonb;

alter table public.inventory_items drop constraint if exists inventory_items_packaging_type_check;
alter table public.inventory_items add constraint inventory_items_packaging_type_check check (
  packaging_type is null or packaging_type in ('bottle','can','carton','keg','bag','box','case','jar','tub','pouch',
    'sachet','tray','bundle','loose','cup','wrapped','cylinder','tool','other')) not valid;
alter table public.inventory_items validate constraint inventory_items_packaging_type_check;
alter table public.inventory_items drop constraint if exists inventory_items_unit_size_check;
alter table public.inventory_items add constraint inventory_items_unit_size_check check (
  (unit_size_quantity is null and unit_size_base is null)
  or (unit_size_quantity > 0 and unit_size_base in ('ml','g','count'))) not valid;
alter table public.inventory_items validate constraint inventory_items_unit_size_check;
alter table public.inventory_items drop constraint if exists inventory_items_abv_check;
alter table public.inventory_items add constraint inventory_items_abv_check check (
  abv_percent is null or abv_percent between 0 and 100) not valid;
alter table public.inventory_items validate constraint inventory_items_abv_check;
alter table public.inventory_items drop constraint if exists inventory_items_item_class_check;
alter table public.inventory_items add constraint inventory_items_item_class_check check (
  item_class is null or item_class in ('spirit','liqueur','wine','sparkling','beer_cider','non_alcoholic','syrup',
    'bar_ingredient','dairy_alt','coffee_tea','produce','garnish','food','consumable','cleaning','equipment','gas',
    'prep','reference')) not valid;
alter table public.inventory_items validate constraint inventory_items_item_class_check;
alter table public.inventory_items drop constraint if exists inventory_items_attributes_source_check;
alter table public.inventory_items add constraint inventory_items_attributes_source_check check (
  attributes_source is null or jsonb_typeof(attributes_source) = 'object') not valid;
alter table public.inventory_items validate constraint inventory_items_attributes_source_check;

comment on column public.inventory_items.canonical_key is
  'Legacy concept key (recipe mappings and aliases depend on it). Not an identity key; see atlas_private.inventory_identity_keys.';

create table if not exists atlas_private.inventory_taxonomy (
  id integer generated always as identity primary key,
  item_class text not null check (item_class in ('spirit','liqueur','wine','sparkling','beer_cider','non_alcoholic',
    'syrup','bar_ingredient','dairy_alt','coffee_tea','produce','garnish','food','consumable','cleaning','equipment',
    'gas','prep','reference')),
  category text not null check (char_length(btrim(category)) between 1 and 120),
  subcategory text check (subcategory is null or char_length(btrim(subcategory)) between 1 and 120),
  default_packaging text,
  default_count_unit text,
  counts_partials boolean not null default false,
  has_abv boolean not null default false,
  sort integer not null default 100
);
create unique index if not exists inventory_taxonomy_category_uidx
  on atlas_private.inventory_taxonomy (lower(category), coalesce(lower(subcategory), ''));
alter table atlas_private.inventory_taxonomy enable row level security;
revoke all on atlas_private.inventory_taxonomy from public, anon, authenticated;
grant all on atlas_private.inventory_taxonomy to service_role;
drop policy if exists inventory_taxonomy_service_only on atlas_private.inventory_taxonomy;
create policy inventory_taxonomy_service_only on atlas_private.inventory_taxonomy
  for all to service_role using (true) with check (true);

-- Reference rows only (no inventory row is touched). Production category
-- names are kept as written; "A › B" categories match on the part before ›.
insert into atlas_private.inventory_taxonomy (item_class, category, subcategory, default_packaging, default_count_unit, counts_partials, has_abv, sort)
values
  ('spirit','Gin',null,'bottle','bottle',true,true,10),
  ('spirit','Vodka',null,'bottle','bottle',true,true,11),
  ('spirit','Rum',null,'bottle','bottle',true,true,12),
  ('spirit','Tequila / Mezcal',null,'bottle','bottle',true,true,13),
