-- Read-only class lookup for a category text ("Coffee & Hot Drinks › Plant Milk").
create or replace function atlas_private.inventory_class_for_category(p_category text, p_subcategory text default null)
returns text
language sql
stable
set search_path = ''
as $function$
  with parts as (
    select lower(btrim(split_part(coalesce(p_category, ''), '›', 1))) as root,
           lower(btrim(coalesce(nullif(btrim(split_part(coalesce(p_category, ''), '›', 2)), ''), p_subcategory, ''))) as sub
  )
  select t.item_class
  from atlas_private.inventory_taxonomy t, parts
  where lower(t.category) = parts.root
    and (t.subcategory is null or lower(t.subcategory) = parts.sub)
  order by (t.subcategory is not null) desc, t.sort
  limit 1;
$function$;

