-- 3. Derived identity keys (an index over existing rows, not canonical data)
-- ---------------------------------------------------------------------------
create table if not exists atlas_private.inventory_identity_keys (
  item_id uuid primary key references public.inventory_items(id) on delete cascade,
  name_key text,
  pack_key text not null default '?',
  identity_key text,
  active boolean not null,
  version text not null,
  updated_at timestamptz not null default now()
);
create index if not exists inventory_identity_keys_name_idx on atlas_private.inventory_identity_keys (name_key);
alter table atlas_private.inventory_identity_keys enable row level security;
revoke all on atlas_private.inventory_identity_keys from public, anon, authenticated;
grant all on atlas_private.inventory_identity_keys to service_role;
drop policy if exists inventory_identity_keys_service_only on atlas_private.inventory_identity_keys;
create policy inventory_identity_keys_service_only on atlas_private.inventory_identity_keys
  for all to service_role using (true) with check (true);

-- ---------------------------------------------------------------------------
-- 4. Codes: new codes only. Legacy sku/barcode/supplier_product_reference and
--    scanner aliases stay where they are and are read through the lookup view.
-- ---------------------------------------------------------------------------
create table if not exists atlas_private.inventory_item_codes (
  id uuid primary key default gen_random_uuid(),
  item_id uuid not null references public.inventory_items(id) on delete restrict,
  kind text not null check (kind in ('gtin','sku','supplier_ref','internal','other_barcode')),
  code_raw text not null check (char_length(code_raw) between 1 and 128),
  code_normalized text not null check (char_length(code_normalized) between 3 and 128),
  symbology text not null default 'unknown',
  supplier_id uuid references public.suppliers(id) on delete restrict,
  pack_level text not null default 'unit' check (pack_level in ('unit','inner','case')),
  units_in_pack numeric check (units_in_pack is null or units_in_pack > 0),
  status text not null default 'active' check (status in ('active','retired')),
  source text not null check (source in ('item_master','manager','import','recognition_confirmed','supplier_document','duplicate_resolution')),
  change_request_id uuid,
  created_by uuid,
  created_by_label text,
  created_at timestamptz not null default now(),
  retired_by uuid,
  retired_at timestamptz,
  retired_reason text,
  check (kind <> 'supplier_ref' or supplier_id is not null),
  check (pack_level = 'unit' or units_in_pack is not null),
  check (status = 'active' or retired_at is not null)
);
create unique index if not exists inventory_item_codes_active_global_uidx
  on atlas_private.inventory_item_codes (kind, code_normalized) where status = 'active' and kind <> 'supplier_ref';
create unique index if not exists inventory_item_codes_active_supplier_uidx
  on atlas_private.inventory_item_codes (supplier_id, code_normalized) where status = 'active' and kind = 'supplier_ref';
create index if not exists inventory_item_codes_item_idx on atlas_private.inventory_item_codes (item_id) where status = 'active';
create index if not exists inventory_item_codes_lookup_idx on atlas_private.inventory_item_codes (code_normalized);
alter table atlas_private.inventory_item_codes enable row level security;
revoke all on atlas_private.inventory_item_codes from public, anon, authenticated;
grant all on atlas_private.inventory_item_codes to service_role;
drop policy if exists inventory_item_codes_service_only on atlas_private.inventory_item_codes;
create policy inventory_item_codes_service_only on atlas_private.inventory_item_codes
  for all to service_role using (true) with check (true);

-- Every code Atlas knows, one row per (item, kind, normalized code).
create or replace view atlas_private.inventory_code_lookup
with (security_invoker = true)
as
  select c.item_id, c.kind, c.code_normalized, c.supplier_id, c.pack_level, c.units_in_pack, c.status,
         'codes'::text as origin, c.id as code_id
  from atlas_private.inventory_item_codes c
  union all
  select i.id, 'sku', n.code->>'normalized', null::uuid, 'unit', null::numeric, 'active', 'legacy_sku', null::uuid
  from public.inventory_items i
  cross join lateral (select atlas_private.product_code_normalize('sku', i.sku) as code) n
  where nullif(btrim(coalesce(i.sku, '')), '') is not null and (n.code->>'valid')::boolean
  union all
  select i.id, n.code->>'kind', n.code->>'normalized', null::uuid, 'unit', null::numeric, 'active', 'legacy_barcode', null::uuid
  from public.inventory_items i
  cross join lateral (
    select case when (atlas_private.product_code_normalize(null, i.barcode)->>'valid')::boolean
                then atlas_private.product_code_normalize(null, i.barcode)
                else atlas_private.product_code_normalize('other_barcode', i.barcode) end as code) n
  where nullif(btrim(coalesce(i.barcode, '')), '') is not null and (n.code->>'valid')::boolean
  union all
  select i.id, 'supplier_ref', n.code->>'normalized', i.supplier_id, 'unit', null::numeric, 'active', 'legacy_supplier_reference', null::uuid
  from public.inventory_items i
  cross join lateral (select atlas_private.product_code_normalize('supplier_ref', i.supplier_product_reference) as code) n
  where nullif(btrim(coalesce(i.supplier_product_reference, '')), '') is not null and (n.code->>'valid')::boolean
  union all
  select a.external_item_id, n.code->>'kind', n.code->>'normalized', null::uuid, 'unit', null::numeric,
         case when a.active then 'active' else 'retired' end, 'legacy_scan_alias', null::uuid
  from atlas_private.inventory_scan_aliases a
  cross join lateral (
    select case when (atlas_private.product_code_normalize(null, a.raw_code)->>'valid')::boolean
                then atlas_private.product_code_normalize(null, a.raw_code)
                else atlas_private.product_code_normalize('other_barcode', a.raw_code) end as code) n
  where (n.code->>'valid')::boolean;
revoke all on atlas_private.inventory_code_lookup from public, anon, authenticated;
grant select on atlas_private.inventory_code_lookup to service_role;

-- Code rows must carry the canonical normalized form and may not take a code
-- another item already holds (in the codes table or a legacy column).
create or replace function private.inventory_item_code_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
  normalized jsonb := atlas_private.product_code_normalize(new.kind, new.code_raw, new.symbology);
  holder uuid;
begin
  if not coalesce((normalized->>'valid')::boolean, false) or normalized->>'kind' <> new.kind then
    raise exception 'This code is not a valid % code', new.kind using errcode = '22023', hint = 'atlas:invalid_code';
  end if;
  new.code_normalized := normalized->>'normalized';
  new.symbology := normalized->>'symbology';
  if new.status = 'active' then
    select l.item_id into holder
    from atlas_private.inventory_code_lookup l
    where l.kind = new.kind and l.code_normalized = new.code_normalized and l.status = 'active'
      and l.item_id <> new.item_id
      and (new.kind <> 'supplier_ref' or l.supplier_id is null or l.supplier_id = new.supplier_id)
      and (l.code_id is null or l.code_id <> new.id)
    limit 1;
    if holder is not null then
      raise exception 'This code is already linked to another inventory item'
        using errcode = '23505', hint = 'atlas:code_conflict', detail = holder::text;
    end if;
  end if;
  return new;
end
$function$;
revoke all on function private.inventory_item_code_guard() from public, anon, authenticated;
drop trigger if exists inventory_item_codes_guard on atlas_private.inventory_item_codes;
create trigger inventory_item_codes_guard
  before insert or update of kind, code_raw, symbology, supplier_id, status on atlas_private.inventory_item_codes
  for each row execute function private.inventory_item_code_guard();

-- ---------------------------------------------------------------------------
-- 5. Aliases: governance columns. Existing rows keep every value; status null
--    means a pre-S89 alias (treated as approved legacy, kind unclassified).
