  add column if not exists created_by_label text,
  add column if not exists approved_by uuid,
  add column if not exists approved_by_label text,
  add column if not exists approved_at timestamptz,
  add column if not exists change_request_id uuid,
  add column if not exists evidence jsonb,
  add column if not exists retired_at timestamptz,
  add column if not exists retired_reason text;

alter table public.inventory_aliases drop constraint if exists inventory_aliases_alias_kind_check;
alter table public.inventory_aliases add constraint inventory_aliases_alias_kind_check check (
  alias_kind is null or alias_kind in ('product_name','recipe_label','supplier_name','ocr_variant','legacy_name')) not valid;
alter table public.inventory_aliases validate constraint inventory_aliases_alias_kind_check;
alter table public.inventory_aliases drop constraint if exists inventory_aliases_status_check;
