  status is null or status in ('pending','approved','rejected','retired')) not valid;
alter table public.inventory_aliases validate constraint inventory_aliases_status_check;
alter table public.inventory_aliases drop constraint if exists inventory_aliases_source_check;
alter table public.inventory_aliases add constraint inventory_aliases_source_check check (
  source is null or source in ('owner_history','manager','recognition','import','ai_proposal','duplicate_resolution')) not valid;
alter table public.inventory_aliases validate constraint inventory_aliases_source_check;
alter table public.inventory_aliases drop constraint if exists inventory_aliases_confidence_check;
alter table public.inventory_aliases add constraint inventory_aliases_confidence_check check (
  confidence is null or confidence between 0 and 100) not valid;
alter table public.inventory_aliases validate constraint inventory_aliases_confidence_check;
alter table public.inventory_aliases drop constraint if exists inventory_aliases_governed_check;
alter table public.inventory_aliases add constraint inventory_aliases_governed_check check (
  status is null or (alias_kind is not null and source is not null)) not valid;
alter table public.inventory_aliases validate constraint inventory_aliases_governed_check;

-- One approved product-level alias per identity name key (letters kept).
create unique index if not exists inventory_aliases_approved_name_key_uidx
  on public.inventory_aliases (atlas_private.product_name_key(null, null, null, alias))
  where status = 'approved' and alias_kind in ('product_name','supplier_name','ocr_variant','legacy_name');
create index if not exists inventory_aliases_status_idx on public.inventory_aliases (status, item_id);

-- ---------------------------------------------------------------------------
-- 6. Derived search documents (search-only keys live here and nowhere else)
-- ---------------------------------------------------------------------------
create table if not exists atlas_private.inventory_search_documents (
  item_id uuid primary key references public.inventory_items(id) on delete cascade,
  search_text text not null,
  match_key text,
  alias_match_keys text[] not null default '{}',
  legacy_key text,
  brand_key text,
  tsv tsvector not null,
  version text not null,
  updated_at timestamptz not null default now()
);
create index if not exists inventory_search_documents_tsv_idx on atlas_private.inventory_search_documents using gin (tsv);
create index if not exists inventory_search_documents_match_idx on atlas_private.inventory_search_documents (match_key);
create index if not exists inventory_search_documents_alias_idx on atlas_private.inventory_search_documents using gin (alias_match_keys);
alter table atlas_private.inventory_search_documents enable row level security;
revoke all on atlas_private.inventory_search_documents from public, anon, authenticated;
grant all on atlas_private.inventory_search_documents to service_role;
drop policy if exists inventory_search_documents_service_only on atlas_private.inventory_search_documents;
create policy inventory_search_documents_service_only on atlas_private.inventory_search_documents
  for all to service_role using (true) with check (true);

-- Aliases that count as product evidence: approved non-recipe aliases and
-- pre-S89 aliases (status null) that are not recipe labels.
create or replace function atlas_private.inventory_alias_is_product_evidence(p_status text, p_kind text)
returns boolean
language sql
immutable
set search_path = ''
as $function$
  select (p_status = 'approved' and p_kind in ('product_name','supplier_name','ocr_variant','legacy_name'))
      or (p_status is null and (p_kind is null or p_kind <> 'recipe_label'));
$function$;

create or replace function atlas_private.inventory_search_refresh(p_item_id uuid)
returns void
language plpgsql
set search_path = ''
as $function$
declare
  item_row public.inventory_items;
  alias_texts text;
  alias_keys text[];
  text_value text;
begin
  select * into item_row from public.inventory_items where id = p_item_id;
  if not found then
    delete from atlas_private.inventory_search_documents where item_id = p_item_id;
    return;
  end if;
  select string_agg(a.alias, ' ' order by a.alias),
         coalesce(array_agg(distinct k.key) filter (where k.key is not null), '{}')
  into alias_texts, alias_keys
  from public.inventory_aliases a
  cross join lateral (select atlas_private.product_match_key(null, null, null, a.alias) as key) k
  where a.item_id = p_item_id
    and atlas_private.inventory_alias_is_product_evidence(a.status, a.alias_kind);
  text_value := atlas_private.product_search_fold(concat_ws(' ', item_row.name, item_row.brand, item_row.product_name,
    item_row.variant, alias_texts));
  insert into atlas_private.inventory_search_documents
    (item_id, search_text, match_key, alias_match_keys, legacy_key, brand_key, tsv, version, updated_at)
  values (
    p_item_id,
    text_value,
    atlas_private.product_match_key(item_row.brand, item_row.product_name, item_row.variant, item_row.name),
    coalesce(alias_keys, '{}'),
    atlas_private.product_match_key(null, null, null, pg_catalog.regexp_replace(coalesce(item_row.canonical_key, ''), '[-_:]+', ' ', 'g')),
    atlas_private.product_match_key(null, null, null, item_row.brand),
    pg_catalog.to_tsvector('simple'::regconfig, text_value),
    atlas_private.product_identity_constants()->>'version',
    now())
  on conflict (item_id) do update set
    search_text = excluded.search_text, match_key = excluded.match_key, alias_match_keys = excluded.alias_match_keys,
    legacy_key = excluded.legacy_key, brand_key = excluded.brand_key, tsv = excluded.tsv,
    version = excluded.version, updated_at = excluded.updated_at;
end
$function$;

create or replace function atlas_private.inventory_identity_refresh(p_item_id uuid)
returns void
language plpgsql
set search_path = ''
as $function$
declare
  item_row public.inventory_items;
  key_name text;
  key_pack text;
  key_identity text;
  holder public.inventory_items;
begin
  select * into item_row from public.inventory_items where id = p_item_id;
  if not found then
    delete from atlas_private.inventory_identity_keys where item_id = p_item_id;
    return;
  end if;
  key_name := atlas_private.product_name_key(item_row.brand, item_row.product_name, item_row.variant, item_row.name);
  key_pack := atlas_private.product_pack_key(item_row.unit_size_quantity, item_row.unit_size_base, item_row.size_ml,
    item_row.package_weight_g, item_row.package_size, item_row.name, item_row.unit);
  key_identity := case when key_name is null then null else key_name || '|' || key_pack end;
  if item_row.active and key_identity is not null then
    select other.* into holder
    from atlas_private.inventory_identity_keys k
    join public.inventory_items other on other.id = k.item_id
    where k.identity_key = key_identity and k.active and k.item_id <> p_item_id
    limit 1;
    if found then
      raise exception 'An active item with the same name and package already exists: %', holder.name
        using errcode = '23505', hint = 'atlas:duplicate_identity', detail = holder.id::text;
    end if;
  end if;
  insert into atlas_private.inventory_identity_keys (item_id, name_key, pack_key, identity_key, active, version, updated_at)
  values (p_item_id, key_name, key_pack, key_identity, item_row.active,
          atlas_private.product_identity_constants()->>'version', now())
  on conflict (item_id) do update set
    name_key = excluded.name_key, pack_key = excluded.pack_key, identity_key = excluded.identity_key,
    active = excluded.active, version = excluded.version, updated_at = excluded.updated_at;
end
$function$;

-- Trigger bodies are definer: a manager's direct browser edit fires them and
-- they write only the derived tables.
create or replace function private.inventory_item_identity_sync()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
begin
  perform atlas_private.inventory_identity_refresh(new.id);
  perform atlas_private.inventory_search_refresh(new.id);
  return null;
end
$function$;
revoke all on function private.inventory_item_identity_sync() from public, anon, authenticated;

drop trigger if exists inventory_items_s89_identity_sync on public.inventory_items;
create trigger inventory_items_s89_identity_sync
  after insert or update of name, brand, product_name, variant, unit_size_quantity, unit_size_base, size_ml,
    package_weight_g, package_size, unit, active, canonical_key
  on public.inventory_items
  for each row execute function private.inventory_item_identity_sync();

create or replace function private.inventory_alias_search_sync()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
begin
  if tg_op in ('UPDATE', 'DELETE') and old.item_id is not null then
    perform atlas_private.inventory_search_refresh(old.item_id);
  end if;
  if tg_op in ('INSERT', 'UPDATE') and new.item_id is not null then
    perform atlas_private.inventory_search_refresh(new.item_id);
  end if;
  return null;
end
$function$;
revoke all on function private.inventory_alias_search_sync() from public, anon, authenticated;

drop trigger if exists inventory_aliases_s89_search_sync on public.inventory_aliases;
create trigger inventory_aliases_s89_search_sync
  after insert or update or delete on public.inventory_aliases
  for each row execute function private.inventory_alias_search_sync();

-- Index the existing rows. Nothing on inventory_items is written.
insert into atlas_private.inventory_identity_keys (item_id, name_key, pack_key, identity_key, active, version)
select k.id, k.name_key, k.pack_key,
       case when k.name_key is null then null else k.name_key || '|' || k.pack_key end,
       k.active, atlas_private.product_identity_constants()->>'version'
from (
  select i.id, i.active,
         atlas_private.product_name_key(i.brand, i.product_name, i.variant, i.name) as name_key,
         atlas_private.product_pack_key(i.unit_size_quantity, i.unit_size_base, i.size_ml, i.package_weight_g,
           i.package_size, i.name, i.unit) as pack_key
  from public.inventory_items i
) k
on conflict (item_id) do nothing;

-- Pre-flight: never merge anything automatically. Existing active duplicates
-- abort the migration with the list so a manager can resolve them first.
do $s89_identity_preflight$
declare
  groups text;
begin
  select string_agg(format('%s: %s', g.identity_key, g.names), '; ' order by g.identity_key) into groups
  from (
    select k.identity_key, string_agg(i.name || ' (' || i.id || ')', ', ' order by i.name) as names
    from atlas_private.inventory_identity_keys k
    join public.inventory_items i on i.id = k.item_id
    where k.active and k.identity_key is not null
    group by k.identity_key
    having count(*) > 1
  ) g;
  if groups is not null then
    raise exception 'S89 identity pre-flight: active items share a name and package. Resolve before migrating: %', groups
      using hint = 'atlas:duplicate_identity';
  end if;
end
$s89_identity_preflight$;

create unique index if not exists inventory_identity_keys_active_uidx
  on atlas_private.inventory_identity_keys (identity_key) where active and identity_key is not null;

do $s89_search_index$
begin
  perform atlas_private.inventory_search_refresh(i.id) from public.inventory_items i;
end
$s89_search_index$;

-- Trigram search is optional. This creates the index only when pg_trgm is
-- already installed (rollout approval item); it never installs the extension.
create or replace function atlas_private.product_trgm_schema()
returns text
language sql
stable
set search_path = ''
as $function$
  select n.nspname::text
  from pg_catalog.pg_extension e
  join pg_catalog.pg_namespace n on n.oid = e.extnamespace
  where e.extname = 'pg_trgm';
$function$;

create or replace function atlas_private.inventory_search_enable_trigram()
returns boolean
language plpgsql
set search_path = ''
as $function$
declare
  trgm_schema text := atlas_private.product_trgm_schema();
begin
  if trgm_schema is null then
    return false;
  end if;
  execute format(
    'create index if not exists inventory_search_documents_trgm_idx on atlas_private.inventory_search_documents using gin (search_text %I.gin_trgm_ops)',
    trgm_schema);
  return true;
end
$function$;
revoke all on function atlas_private.inventory_search_enable_trigram() from public, anon, authenticated;

do $s89_trigram$
begin
  perform atlas_private.inventory_search_enable_trigram();
end
$s89_trigram$;

-- ---------------------------------------------------------------------------
-- 7. Recognition audit tables and media purpose/retention
-- ---------------------------------------------------------------------------
alter table atlas_private.ai_media
  add column if not exists purpose text,
  add column if not exists retention_reason text;
alter table atlas_private.ai_media drop constraint if exists ai_media_purpose_check;
alter table atlas_private.ai_media add constraint ai_media_purpose_check check (
  purpose is null or purpose in ('conversation','recognition','product_reference')) not valid;
alter table atlas_private.ai_media validate constraint ai_media_purpose_check;
alter table atlas_private.ai_media drop constraint if exists ai_media_retention_reason_check;
alter table atlas_private.ai_media add constraint ai_media_retention_reason_check check (
  retention_reason is null or retention_reason in ('pending_review','disputed_match','approved_change','product_image')) not valid;
alter table atlas_private.ai_media validate constraint ai_media_retention_reason_check;
-- A retained image has no expiry; a temporary one must expire.
alter table atlas_private.ai_media drop constraint if exists ai_media_recognition_retention_check;
alter table atlas_private.ai_media add constraint ai_media_recognition_retention_check check (
  purpose is distinct from 'recognition' or (retention_reason is null) = (expires_at is not null)) not valid;
alter table atlas_private.ai_media validate constraint ai_media_recognition_retention_check;

create table if not exists atlas_private.recognition_requests (
  id uuid primary key default gen_random_uuid(),
  client_request_id uuid not null unique,
  actor_id uuid not null,
  actor_label text not null,
  actor_role text not null check (actor_role in ('admin','manager','bartender','viewer')),
  mode text not null check (mode in ('count','identify','add_product','receiving','ai','search')),
  context jsonb not null default '{}'::jsonb check (jsonb_typeof(context) = 'object'),
  media_id uuid references atlas_private.ai_media(id) on delete set null,
  client_barcodes jsonb not null default '[]'::jsonb check (jsonb_typeof(client_barcodes) = 'array'),
  image_quality jsonb,
  vision_model text,
  vision_ms integer check (vision_ms is null or vision_ms >= 0),
  vision_cost_usd numeric check (vision_cost_usd is null or vision_cost_usd >= 0),
  extractor_version text not null,
  scorer_version text not null,
  status text not null default 'completed' check (status in ('completed','failed','barcode_only')),
  failure_code text,
  stock_changed boolean not null default false check (stock_changed = false),
  created_at timestamptz not null default now()
);
create index if not exists recognition_requests_actor_idx on atlas_private.recognition_requests (actor_id, created_at desc);

create table if not exists atlas_private.recognition_detections (
  id uuid primary key default gen_random_uuid(),
  request_id uuid not null references atlas_private.recognition_requests(id) on delete cascade,
  detection_index smallint not null check (detection_index between 0 and 11),
  bbox jsonb,
  extracted jsonb not null check (jsonb_typeof(extracted) = 'object'),
  normalized jsonb not null check (jsonb_typeof(normalized) = 'object'),
  field_confidence jsonb not null check (jsonb_typeof(field_confidence) = 'object'),
  band text not null check (band in ('high','medium','low')),
  preselected_item_id uuid,
  unique (request_id, detection_index),
  check (preselected_item_id is null or band = 'high')
);

create table if not exists atlas_private.recognition_candidates (
  detection_id uuid not null references atlas_private.recognition_detections(id) on delete cascade,
  rank smallint not null check (rank between 1 and 25),
  item_id uuid not null,
  score numeric not null check (score between 0 and 1),
  features jsonb not null check (jsonb_typeof(features) = 'object'),
  explanation text not null check (char_length(explanation) <= 2000),
  primary key (detection_id, rank)
);
create index if not exists recognition_candidates_item_idx on atlas_private.recognition_candidates (item_id);

create table if not exists atlas_private.recognition_outcomes (
  id uuid primary key default gen_random_uuid(),
  client_outcome_id uuid unique,
  detection_id uuid not null references atlas_private.recognition_detections(id) on delete cascade,
  outcome text not null check (outcome in ('confirmed_preselected','chose_candidate','chose_by_search','no_match',
    'wrong_product','dismissed','new_product_draft')),
  chosen_item_id uuid,
  chosen_rank smallint,
  used_for text check (used_for in ('count_line','identify','receiving','draft','ai_answer')),
  used_ref jsonb,
  actor_id uuid not null,
  actor_label text not null,
  actor_role text not null check (actor_role in ('admin','manager','bartender','viewer')),
  note text check (note is null or char_length(note) <= 2000),
  created_at timestamptz not null default now(),
  check (outcome not in ('confirmed_preselected','chose_candidate','chose_by_search') or chosen_item_id is not null)
);
create index if not exists recognition_outcomes_actor_idx on atlas_private.recognition_outcomes (actor_id, created_at desc);
create index if not exists recognition_outcomes_item_idx on atlas_private.recognition_outcomes (chosen_item_id);
create index if not exists recognition_outcomes_outcome_idx on atlas_private.recognition_outcomes (outcome, created_at);

do $s89_recognition_tables$
declare
  table_name text;
begin
  foreach table_name in array array['recognition_requests','recognition_detections','recognition_candidates','recognition_outcomes'] loop
    execute format('alter table atlas_private.%I enable row level security', table_name);
    execute format('revoke all on atlas_private.%I from public, anon, authenticated', table_name);
    execute format('grant all on atlas_private.%I to service_role', table_name);
    execute format('drop policy if exists %I on atlas_private.%I', table_name || '_service_only', table_name);
    execute format('create policy %I on atlas_private.%I for all to service_role using (true) with check (true)',
      table_name || '_service_only', table_name);
  end loop;
end
$s89_recognition_tables$;

-- Recognition audit rows are append-only (outcomes and requests are never edited).
create or replace function private.recognition_append_only()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
begin
  raise exception 'Recognition audit rows cannot be changed' using errcode = '42501', hint = 'atlas:append_only';
end
$function$;
revoke all on function private.recognition_append_only() from public, anon, authenticated;
drop trigger if exists recognition_outcomes_append_only on atlas_private.recognition_outcomes;
create trigger recognition_outcomes_append_only before update on atlas_private.recognition_outcomes
  for each row execute function private.recognition_append_only();
drop trigger if exists recognition_candidates_append_only on atlas_private.recognition_candidates;
create trigger recognition_candidates_append_only before update on atlas_private.recognition_candidates
  for each row execute function private.recognition_append_only();

-- ---------------------------------------------------------------------------
-- 8. The legacy scanner can never apply a count to stock again
-- ---------------------------------------------------------------------------
update atlas_private.inventory_scanner_settings set live_apply_enabled = false where live_apply_enabled;
alter table atlas_private.inventory_scanner_settings drop constraint if exists inventory_scanner_settings_no_live_apply;
alter table atlas_private.inventory_scanner_settings add constraint inventory_scanner_settings_no_live_apply
  check (live_apply_enabled = false) not valid;
alter table atlas_private.inventory_scanner_settings validate constraint inventory_scanner_settings_no_live_apply;
alter table atlas_private.inventory_scan_events drop constraint if exists inventory_scan_events_no_live_status;
alter table atlas_private.inventory_scan_events add constraint inventory_scan_events_no_live_status
  check (status not in ('pending_live','live_applied')) not valid;

-- ---------------------------------------------------------------------------
-- 9. Recognition definer role: read catalogue, write recognition audit only
-- ---------------------------------------------------------------------------
do $s89_role$
begin
  if not exists (select 1 from pg_catalog.pg_roles where rolname = 'atlas_recognition_definer') then
    create role atlas_recognition_definer nologin noinherit;
  end if;
  -- The migration role must be able to hand function ownership to it.
  execute format('grant atlas_recognition_definer to %I', current_user);
end
$s89_role$;
alter role atlas_recognition_definer nologin noinherit;

grant usage on schema public, atlas_private to atlas_recognition_definer;
do $s89_role_extensions$
begin
  if exists (select 1 from pg_catalog.pg_namespace where nspname = 'extensions') then
    grant usage on schema extensions to atlas_recognition_definer;
  end if;
end
$s89_role_extensions$;

grant select on public.inventory_items, public.suppliers, public.inventory_aliases, public.purchase_orders
  to atlas_recognition_definer;
grant select (id, role, active) on public.profiles to atlas_recognition_definer;
grant select on atlas_private.inventory_item_codes, atlas_private.inventory_identity_keys,
  atlas_private.inventory_search_documents, atlas_private.inventory_taxonomy, atlas_private.inventory_code_lookup,
  atlas_private.inventory_scan_aliases, atlas_private.inventory_count_sessions, atlas_private.inventory_count_lines,
  atlas_private.inventory_verified_balances, atlas_private.ai_settings
  to atlas_recognition_definer;
grant select, insert on atlas_private.recognition_requests, atlas_private.recognition_detections,
  atlas_private.recognition_candidates, atlas_private.recognition_outcomes to atlas_recognition_definer;
grant select, insert on atlas_private.ai_media to atlas_recognition_definer;
grant update (expires_at, retention_reason) on atlas_private.ai_media to atlas_recognition_definer;

-- Row policies for the role on every table it reads or appends to.
do $s89_role_policies$
declare
  target record;
begin
  for target in
    select * from (values
      ('public','inventory_items','select'), ('public','suppliers','select'), ('public','inventory_aliases','select'),
      ('public','purchase_orders','select'), ('public','profiles','select'),
      ('atlas_private','inventory_item_codes','select'), ('atlas_private','inventory_identity_keys','select'),
      ('atlas_private','inventory_search_documents','select'), ('atlas_private','inventory_taxonomy','select'),
      ('atlas_private','inventory_scan_aliases','select'), ('atlas_private','inventory_count_sessions','select'),
      ('atlas_private','inventory_count_lines','select'), ('atlas_private','inventory_verified_balances','select'),
      ('atlas_private','ai_settings','select'),
      ('atlas_private','recognition_requests','select'), ('atlas_private','recognition_requests','insert'),
      ('atlas_private','recognition_detections','select'), ('atlas_private','recognition_detections','insert'),
      ('atlas_private','recognition_candidates','select'), ('atlas_private','recognition_candidates','insert'),
      ('atlas_private','recognition_outcomes','select'), ('atlas_private','recognition_outcomes','insert'),
      ('atlas_private','ai_media','select'), ('atlas_private','ai_media','insert'), ('atlas_private','ai_media','update')
    ) as v(schema_name, table_name, command)
  loop
    execute format('drop policy if exists %I on %I.%I',
      'recognition definer ' || target.command, target.schema_name, target.table_name);
    if target.command = 'select' then
      execute format('create policy %I on %I.%I for select to atlas_recognition_definer using (true)',
        'recognition definer ' || target.command, target.schema_name, target.table_name);
    elsif target.command = 'insert' then
      execute format('create policy %I on %I.%I for insert to atlas_recognition_definer with check (true)',
        'recognition definer ' || target.command, target.schema_name, target.table_name);
    else
      execute format('create policy %I on %I.%I for update to atlas_recognition_definer using (purpose = %L) with check (purpose = %L)',
        'recognition definer ' || target.command, target.schema_name, target.table_name, 'recognition', 'recognition');
    end if;
  end loop;
end
$s89_role_policies$;

-- ---------------------------------------------------------------------------
-- Recognition read and record commands (bodies run as the definer role)
-- ---------------------------------------------------------------------------
create or replace function atlas_private.recognition_actor(p_actor_id uuid, p_actor_role text)
returns text
language plpgsql
stable
set search_path = ''
as $function$
declare
  actual text;
begin
  select profile.role::text into actual from public.profiles profile
  where profile.id = p_actor_id and profile.active is true;
  if p_actor_id is null or actual is null or actual not in ('admin','manager','bartender','viewer') then
    raise exception 'Active Atlas staff access required' using errcode = '42501', hint = 'atlas:forbidden';
  end if;
  if p_actor_role is not null and p_actor_role <> actual then
    raise exception 'Atlas role changed. Sign in again.' using errcode = '42501', hint = 'atlas:forbidden';
  end if;
  return actual;
end
$function$;

-- Item summary for recognition. Supplier fields only for managers; costs never.
create or replace function atlas_private.recognition_item_payload(p_item public.inventory_items, p_role text)
returns jsonb
language sql
stable
set search_path = ''
as $function$
  select jsonb_build_object(
    'id', p_item.id, 'name', p_item.name, 'brand', p_item.brand, 'product_name', p_item.product_name,
    'variant', p_item.variant, 'category', p_item.category, 'subcategory', p_item.subcategory,
    'item_class', coalesce(p_item.item_class, atlas_private.inventory_class_for_category(p_item.category, p_item.subcategory)),
    'item_class_source', case when p_item.item_class is not null then 'item' else 'category_map' end,
    'packaging_type', p_item.packaging_type, 'unit', p_item.unit,
    'unit_size_quantity', p_item.unit_size_quantity, 'unit_size_base', p_item.unit_size_base,
    'size_ml', p_item.size_ml, 'package_weight_g', p_item.package_weight_g, 'package_size', p_item.package_size,
    'units_per_case', p_item.units_per_case, 'abv_percent', p_item.abv_percent,
    'image_url', p_item.image_url, 'bin_location', p_item.bin_location, 'par_level', p_item.par_level,
    'active', p_item.active,
    'name_key', k.name_key, 'pack_key', k.pack_key, 'identity_key', k.identity_key,
    'match_key', d.match_key, 'brand_key', d.brand_key)
  || case when p_role in ('admin','manager') then jsonb_build_object(
       'supplier_id', p_item.supplier_id,
       'supplier_name', (select s.name from public.suppliers s where s.id = p_item.supplier_id))
     else '{}'::jsonb end
  from (select 1) one
  left join atlas_private.inventory_identity_keys k on k.item_id = p_item.id
  left join atlas_private.inventory_search_documents d on d.item_id = p_item.id;
$function$;

create or replace function atlas_private.recognition_resolve_codes(p_codes jsonb, p_actor_id uuid, p_actor_role text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  role_name text := atlas_private.recognition_actor(p_actor_id, p_actor_role);
  entry jsonb;
  normalized jsonb;
  results jsonb := '[]'::jsonb;
  matches jsonb;
  active_items uuid[];
begin
  if jsonb_typeof(coalesce(p_codes, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_codes, '[]'::jsonb)) > 20 then
    raise exception 'Up to 20 codes can be resolved at once' using errcode = '22023', hint = 'atlas:invalid_request';
  end if;
  for entry in select value from jsonb_array_elements(coalesce(p_codes, '[]'::jsonb)) loop
    normalized := atlas_private.product_code_normalize(entry->>'kind', coalesce(entry->>'raw', entry->>'normalized'), entry->>'symbology');
    if not (normalized->>'valid')::boolean and entry->>'kind' is null and normalized->>'reason' = 'check_digit' then
      -- A numeric code that fails the GTIN check may still be an internal barcode.
      normalized := atlas_private.product_code_normalize('other_barcode', coalesce(entry->>'raw', entry->>'normalized'), entry->>'symbology')
        || jsonb_build_object('gtin_check_failed', true);
    end if;
    select coalesce(jsonb_agg(jsonb_build_object(
             'item_id', l.item_id, 'name', i.name, 'active', i.active, 'unit', i.unit, 'category', i.category,
             'code_status', l.status, 'origin', l.origin, 'kind', l.kind, 'pack_level', l.pack_level,
             'units_in_pack', l.units_in_pack)
             || case when role_name in ('admin','manager') then jsonb_build_object('supplier_id', l.supplier_id) else '{}'::jsonb end
             order by l.status, i.name), '[]'::jsonb),
           coalesce(array_agg(distinct l.item_id) filter (where l.status = 'active' and i.active), '{}')
    into matches, active_items
    from atlas_private.inventory_code_lookup l
    join public.inventory_items i on i.id = l.item_id
    where (normalized->>'valid')::boolean
      and l.kind = normalized->>'kind' and l.code_normalized = normalized->>'normalized'
      and (l.kind <> 'supplier_ref' or entry->>'supplier_id' is null or l.supplier_id is null
           or l.supplier_id::text = entry->>'supplier_id');
    results := results || jsonb_build_object(
      'input', entry,
      'kind', normalized->>'kind',
      'normalized', normalized->>'normalized',
      'valid', (normalized->>'valid')::boolean,
      'reason', normalized->>'reason',
      'gtin_check_failed', coalesce((normalized->>'gtin_check_failed')::boolean, false),
      'matches', matches,
      'unique_active_item_id', case when pg_catalog.cardinality(active_items) = 1 then active_items[1] end,
      'collision', pg_catalog.cardinality(active_items) > 1);
  end loop;
  return jsonb_build_object('codes', results, 'stock_changed', false);
end
$function$;

create or replace function atlas_private.recognition_json_text_array(p_value jsonb)
returns text[]
language sql
immutable
set search_path = ''
as $function$
  select coalesce(array_agg(distinct v) filter (where v is not null and v <> ''), '{}')
  from jsonb_array_elements_text(case when jsonb_typeof(p_value) = 'array' then p_value else '[]'::jsonb end) v;
$function$;

-- Candidate retrieval with every feature the scorer needs. Deterministic;
-- trigram similarity is used only when pg_trgm is installed.
create or replace function atlas_private.recognition_candidate_features(
  p_signals jsonb, p_limit integer, p_actor_id uuid, p_actor_role text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  role_name text := atlas_private.recognition_actor(p_actor_id, p_actor_role);
  signals jsonb := coalesce(p_signals, '{}'::jsonb);
  row_limit integer := least(greatest(coalesce(p_limit, 25), 1), 50);
  texts text[] := atlas_private.recognition_json_text_array(signals->'texts');
  name_keys text[] := atlas_private.recognition_json_text_array(signals->'name_keys');
  match_keys text[] := atlas_private.recognition_json_text_array(signals->'match_keys');
  identity_keys text[] := atlas_private.recognition_json_text_array(signals->'identity_keys');
  v_brand_key text := atlas_private.product_match_key(null, null, null, signals->>'brand');
  query_text text;
  query_tokens text[];
  trgm_schema text := atlas_private.product_trgm_schema();
  text_scores jsonb := '{}'::jsonb;
  method text := 'fts';
  v_session_id uuid;
  v_order_id uuid;
  context_supplier uuid;
  t text;
  result jsonb;
begin
  if jsonb_typeof(signals) <> 'object' then
    raise exception 'Signals must be an object' using errcode = '22023', hint = 'atlas:invalid_request';
  end if;
  foreach t in array texts loop
    name_keys := name_keys || atlas_private.product_name_key(null, null, null, t);
    match_keys := match_keys || atlas_private.product_match_key(null, null, null, t);
  end loop;
  name_keys := array_remove(name_keys, null);
  match_keys := array_remove(match_keys, null);
  query_text := atlas_private.product_search_fold(concat_ws(' ', signals->>'query', array_to_string(texts, ' '), signals->>'brand'));
  select coalesce(array_agg(distinct q), '{}') into query_tokens
  from unnest(string_to_array(query_text, ' ')) q where char_length(q) >= 2;
  begin
    v_session_id := nullif(signals->'context'->>'count_session_id', '')::uuid;
    v_order_id := nullif(signals->'context'->>'purchase_order_id', '')::uuid;
    context_supplier := nullif(signals->'context'->>'supplier_id', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'Context ids must be UUIDs' using errcode = '22023', hint = 'atlas:invalid_request';
  end;

  if query_text <> '' then
    if trgm_schema is not null then
      method := 'trigram';
      execute format(
        'select coalesce(jsonb_object_agg(item_id, score), ''{}''::jsonb) from (
           select d.item_id, round(%1$I.similarity(d.search_text, $1)::numeric, 3) as score
           from atlas_private.inventory_search_documents d
           where %1$I.similarity(d.search_text, $1) >= 0.25
           order by 2 desc, d.item_id limit 15) s', trgm_schema)
      into text_scores using query_text;
    elsif cardinality(query_tokens) > 0 then
      select coalesce(jsonb_object_agg(item_id, score), '{}'::jsonb) into text_scores
      from (
        select d.item_id,
               round(ts_rank(d.tsv, to_tsquery('simple'::regconfig, array_to_string(
                 array(select quote_literal(q) from unnest(query_tokens) q), ' | ')))::numeric, 4) as score
        from atlas_private.inventory_search_documents d
        where d.tsv @@ to_tsquery('simple'::regconfig, array_to_string(
                array(select quote_literal(q) from unnest(query_tokens) q), ' | '))
        order by 2 desc, d.item_id
        limit 15
      ) s;
    end if;
  end if;

  with code_signals as (
    select c->>'kind' as kind, c->>'normalized' as normalized, nullif(c->>'supplier_id', '') as supplier_id
    from jsonb_array_elements(case when jsonb_typeof(signals->'codes') = 'array' then signals->'codes' else '[]'::jsonb end) c
    where nullif(c->>'normalized', '') is not null
  ), code_hits as (
    select l.item_id, jsonb_agg(jsonb_build_object('kind', l.kind, 'pack_level', l.pack_level,
             'units_in_pack', l.units_in_pack, 'status', l.status, 'origin', l.origin,
             'supplier_scoped', l.kind = 'supplier_ref' and s.supplier_id is not null)) as hits
    from atlas_private.inventory_code_lookup l
    join code_signals s on s.kind = l.kind and s.normalized = l.code_normalized
      and (l.kind <> 'supplier_ref' or s.supplier_id is null or l.supplier_id is null or l.supplier_id::text = s.supplier_id)
    group by l.item_id
  ), alias_hits as (
    select a.item_id, jsonb_agg(jsonb_build_object('alias', a.alias, 'alias_kind', coalesce(a.alias_kind, 'unclassified'),
             'status', coalesce(a.status, 'legacy'))) as hits
    from public.inventory_aliases a
    where a.item_id is not null
      and (a.status is null or a.status = 'approved')
      and atlas_private.product_match_key(null, null, null, a.alias) = any(match_keys)
    group by a.item_id
  ), pool as (
    select item_id from code_hits
    union select item_id from alias_hits
    union select k.item_id from atlas_private.inventory_identity_keys k where k.identity_key = any(identity_keys) or k.name_key = any(name_keys)
    union select d.item_id from atlas_private.inventory_search_documents d where d.match_key = any(match_keys)
    union select key::uuid from jsonb_object_keys(text_scores) key
    union select d.item_id from atlas_private.inventory_search_documents d
      where v_brand_key is not null and (d.brand_key = v_brand_key or v_brand_key = any(string_to_array(coalesce(d.match_key, ''), ' ')))
  ), features as (
    select i, k, d,
      jsonb_build_object(
        'code_matches', coalesce(ch.hits, '[]'::jsonb),
        'alias_matches', coalesce(ah.hits, '[]'::jsonb),
        'identity_exact', coalesce(k.identity_key = any(identity_keys), false),
        'name_key_exact', coalesce(k.name_key = any(name_keys), false),
        'match_key_exact', coalesce(d.match_key = any(match_keys), false),
        'text_score', coalesce((text_scores->>i.id::text)::numeric, 0),
        'brand_match', v_brand_key is not null and (d.brand_key = v_brand_key or v_brand_key = any(string_to_array(coalesce(d.match_key, ''), ' '))),
        'in_session', v_session_id is not null and exists (
          select 1 from atlas_private.inventory_count_lines line where line.session_id = v_session_id and line.inventory_item_id = i.id),
        'counted_in_session', v_session_id is not null and exists (
          select 1 from atlas_private.inventory_count_lines line
          where line.session_id = v_session_id and line.inventory_item_id = i.id and line.line_status = 'counted'),
        'on_order', v_order_id is not null and exists (
          select 1 from public.purchase_orders po, jsonb_array_elements(po.lines) line
          where po.id = v_order_id and line->>'item_id' = i.id::text),
        'supplier_match', context_supplier is not null and i.supplier_id = context_supplier,
        'prior_confirmations', (select count(*) from atlas_private.recognition_outcomes o
          join atlas_private.recognition_detections det on det.id = o.detection_id
          where o.chosen_item_id = i.id and o.outcome in ('confirmed_preselected','chose_candidate','chose_by_search')
            and det.normalized->>'match_key' = any(match_keys)),
        'prior_wrong', (select count(*) from atlas_private.recognition_outcomes o
          join atlas_private.recognition_detections det on det.id = o.detection_id
          join atlas_private.recognition_candidates cand on cand.detection_id = det.id and cand.rank = 1
          where o.outcome = 'wrong_product' and cand.item_id = i.id),
        'inactive', not i.active) as feature
    from pool
    join public.inventory_items i on i.id = pool.item_id
    left join atlas_private.inventory_identity_keys k on k.item_id = i.id
    left join atlas_private.inventory_search_documents d on d.item_id = i.id
    left join code_hits ch on ch.item_id = i.id
    left join alias_hits ah on ah.item_id = i.id
    where lower(coalesce(i.unit, '')) <> 'untracked'
      and coalesce(i.item_class, atlas_private.inventory_class_for_category(i.category, i.subcategory), '') not in ('reference', 'prep')
      and (i.active or coalesce((signals->>'include_inactive')::boolean, true))
  )
  select jsonb_build_object(
    'method', method,
    'signals', jsonb_build_object('name_keys', to_jsonb(name_keys), 'match_keys', to_jsonb(match_keys),
      'identity_keys', to_jsonb(identity_keys), 'brand_key', v_brand_key, 'query', query_text),
    'candidates', coalesce(jsonb_agg(jsonb_build_object(
        'item_id', (f.i).id,
        'item', atlas_private.recognition_item_payload(f.i, role_name),
        'aliases', coalesce((select jsonb_agg(a.alias order by a.alias) from public.inventory_aliases a
                             where a.item_id = (f.i).id
                               and atlas_private.inventory_alias_is_product_evidence(a.status, a.alias_kind)), '[]'::jsonb),
        'features', f.feature)
      order by jsonb_array_length(f.feature->'code_matches') desc, (f.feature->>'identity_exact')::boolean desc,
               (f.feature->>'match_key_exact')::boolean desc, (f.feature->>'text_score')::numeric desc, (f.i).name),
      '[]'::jsonb),
    'stock_changed', false)
  into result
  from (select * from features order by jsonb_array_length(feature->'code_matches') desc,
          (feature->>'identity_exact')::boolean desc, (feature->>'match_key_exact')::boolean desc,
          (feature->>'text_score')::numeric desc, (i).name limit row_limit) f;
  return result;
end
$function$;

create or replace function atlas_private.recognition_register_media(p_media jsonb, p_actor_id uuid, p_actor_role text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  role_name text := atlas_private.recognition_actor(p_actor_id, p_actor_role);
  retention integer;
  media_row atlas_private.ai_media;
begin
  if jsonb_typeof(coalesce(p_media, 'null'::jsonb)) <> 'object' then
    raise exception 'Media must be an object' using errcode = '22023', hint = 'atlas:invalid_request';
  end if;
  if coalesce(p_media->>'kind', 'image') <> 'image' then
    raise exception 'Recognition accepts images only' using errcode = '22023', hint = 'atlas:invalid_request';
  end if;
  if pg_catalog.split_part(coalesce(p_media->>'path', ''), '/', 1) <> p_actor_id::text then
    raise exception 'The image path must belong to the uploader' using errcode = '42501', hint = 'atlas:forbidden';
  end if;
  select coalesce(max(s.media_retention_days), 30) into retention from atlas_private.ai_settings s;
  insert into atlas_private.ai_media (user_id, path, mime, bytes, kind, sha256, expires_at, purpose)
  values (p_actor_id, p_media->>'path', p_media->>'mime', (p_media->>'bytes')::bigint, 'image',
          nullif(p_media->>'sha256', ''), now() + make_interval(days => least(greatest(retention, 1), 30)), 'recognition')
  returning * into media_row;
  return jsonb_build_object('media_id', media_row.id, 'expires_at', media_row.expires_at, 'role', role_name, 'stock_changed', false);
end
$function$;

create or replace function atlas_private.recognition_record(
  p_request jsonb, p_actor_id uuid, p_actor_label text, p_actor_role text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $function$
declare
  role_name text := atlas_private.recognition_actor(p_actor_id, p_actor_role);
  request jsonb := coalesce(p_request, '{}'::jsonb);
  existing atlas_private.recognition_requests;
  request_row atlas_private.recognition_requests;
  detection jsonb;
  candidate jsonb;
  detection_row atlas_private.recognition_detections;
  media uuid;
  label text := coalesce(nullif(btrim(coalesce(p_actor_label, '')), ''), p_actor_id::text);
  recorded jsonb := '[]'::jsonb;
  top_item uuid;
begin
  if jsonb_typeof(request) <> 'object' then
    raise exception 'Recognition request must be an object' using errcode = '22023', hint = 'atlas:invalid_request';
  end if;
  if jsonb_typeof(coalesce(request->'detections', '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(request->'detections', '[]'::jsonb)) > 12 then
    raise exception 'Up to 12 detections per image' using errcode = '22023', hint = 'atlas:invalid_request';
  end if;
  begin
    select * into existing from atlas_private.recognition_requests
    where client_request_id = (request->>'client_request_id')::uuid;
    media := nullif(request->>'media_id', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'Request ids must be UUIDs' using errcode = '22023', hint = 'atlas:invalid_request';
  end;
  if request->>'client_request_id' is null then
    raise exception 'A client request id is required' using errcode = '22023', hint = 'atlas:invalid_request';
  end if;
  if existing.id is not null then
    if existing.actor_id <> p_actor_id then
      raise exception 'This request id belongs to another person' using errcode = '42501', hint = 'atlas:forbidden';
    end if;
    return jsonb_build_object('request_id', existing.id, 'replayed', true, 'stock_changed', false,
      'detections', coalesce((select jsonb_agg(jsonb_build_object('detection_index', d.detection_index, 'detection_id', d.id)
                                               order by d.detection_index)
                              from atlas_private.recognition_detections d where d.request_id = existing.id), '[]'::jsonb));
  end if;
  if media is not null and not exists (
    select 1 from atlas_private.ai_media m where m.id = media and m.user_id = p_actor_id and m.deleted_at is null) then
    raise exception 'Image not found' using errcode = 'P0002', hint = 'atlas:not_found';
  end if;

  insert into atlas_private.recognition_requests (
    client_request_id, actor_id, actor_label, actor_role, mode, context, media_id, client_barcodes, image_quality,
    vision_model, vision_ms, vision_cost_usd, extractor_version, scorer_version, status, failure_code)
  values (
    (request->>'client_request_id')::uuid, p_actor_id, label, role_name, request->>'mode',
    coalesce(request->'context', '{}'::jsonb), media, coalesce(request->'client_barcodes', '[]'::jsonb),
    request->'image_quality', nullif(request->>'vision_model', ''), nullif(request->>'vision_ms', '')::integer,
    nullif(request->>'vision_cost_usd', '')::numeric, coalesce(nullif(request->>'extractor_version', ''), 'none'),
    coalesce(nullif(request->>'scorer_version', ''), 'none'), coalesce(nullif(request->>'status', ''), 'completed'),
    nullif(request->>'failure_code', ''))
  returning * into request_row;

  for detection in select value from jsonb_array_elements(coalesce(request->'detections', '[]'::jsonb)) loop
    select (c->>'item_id')::uuid into top_item
    from jsonb_array_elements(coalesce(detection->'candidates', '[]'::jsonb)) c
    where (c->>'rank')::integer = 1;
    if nullif(detection->>'preselected_item_id', '') is not null then
      if detection->>'band' <> 'high' or top_item is null or top_item::text <> detection->>'preselected_item_id'
         or not exists (select 1 from public.inventory_items i where i.id = top_item and i.active) then
        raise exception 'Only the active rank-1 item of a High match can be pre-selected'
          using errcode = '22023', hint = 'atlas:invalid_request';
      end if;
    end if;
    insert into atlas_private.recognition_detections (
      request_id, detection_index, bbox, extracted, normalized, field_confidence, band, preselected_item_id)
    values (
      request_row.id, (detection->>'detection_index')::smallint, detection->'bbox',
      coalesce(detection->'extracted', '{}'::jsonb), coalesce(detection->'normalized', '{}'::jsonb),
      coalesce(detection->'field_confidence', '{}'::jsonb), detection->>'band',
      nullif(detection->>'preselected_item_id', '')::uuid)
    returning * into detection_row;
    for candidate in select value from jsonb_array_elements(coalesce(detection->'candidates', '[]'::jsonb)) loop
      if not exists (select 1 from public.inventory_items i where i.id = (candidate->>'item_id')::uuid) then
        raise exception 'A candidate item does not exist' using errcode = 'P0002', hint = 'atlas:not_found';
      end if;
      insert into atlas_private.recognition_candidates (detection_id, rank, item_id, score, features, explanation)
      values (detection_row.id, (candidate->>'rank')::smallint, (candidate->>'item_id')::uuid,
              (candidate->>'score')::numeric, coalesce(candidate->'features', '{}'::jsonb),
              coalesce(candidate->>'explanation', ''));
    end loop;
    recorded := recorded || jsonb_build_object('detection_index', detection_row.detection_index, 'detection_id', detection_row.id);
  end loop;
  return jsonb_build_object('request_id', request_row.id, 'replayed', false, 'detections', recorded, 'stock_changed', false);
end
$function$;

-- Public wrappers (service_role only). The Edge Function's recognition
-- client may call atlas_recognition_* and nothing else.
create or replace function public.atlas_recognition_resolve_codes(p_codes jsonb, p_actor_id uuid, p_actor_role text)
returns jsonb language sql stable security invoker set search_path = '' as $function$
  select atlas_private.recognition_resolve_codes(p_codes, p_actor_id, p_actor_role);
$function$;
create or replace function public.atlas_recognition_candidates(p_signals jsonb, p_limit integer, p_actor_id uuid, p_actor_role text)
returns jsonb language sql stable security invoker set search_path = '' as $function$
  select atlas_private.recognition_candidate_features(p_signals, p_limit, p_actor_id, p_actor_role);
$function$;
create or replace function public.atlas_recognition_register_media(p_media jsonb, p_actor_id uuid, p_actor_role text)
returns jsonb language sql volatile security invoker set search_path = '' as $function$
  select atlas_private.recognition_register_media(p_media, p_actor_id, p_actor_role);
$function$;
create or replace function public.atlas_recognition_record(p_request jsonb, p_actor_id uuid, p_actor_label text, p_actor_role text)
returns jsonb language sql volatile security invoker set search_path = '' as $function$
  select atlas_private.recognition_record(p_request, p_actor_id, p_actor_label, p_actor_role);
$function$;
create or replace function public.atlas_product_identity(p_values jsonb)
returns jsonb language sql stable security invoker set search_path = '' as $function$
  select jsonb_build_object(
    'fold', atlas_private.product_text_fold(p_values->>'name'),
    'name_key', atlas_private.product_name_key(p_values->>'brand', p_values->>'product_name', p_values->>'variant', p_values->>'name'),
    'match_key', atlas_private.product_match_key(p_values->>'brand', p_values->>'product_name', p_values->>'variant', p_values->>'name'),
    'pack', atlas_private.product_parse_item_package(nullif(p_values->>'unit_size_quantity', '')::numeric, p_values->>'unit_size_base',
      nullif(p_values->>'size_ml', '')::numeric, nullif(p_values->>'package_weight_g', '')::numeric, p_values->>'package_size',
      p_values->>'name', p_values->>'unit'),
    'identity_key', atlas_private.product_identity_key(p_values->>'brand', p_values->>'product_name', p_values->>'variant',
      p_values->>'name', nullif(p_values->>'unit_size_quantity', '')::numeric, p_values->>'unit_size_base',
      nullif(p_values->>'size_ml', '')::numeric, nullif(p_values->>'package_weight_g', '')::numeric,
      p_values->>'package_size', p_values->>'unit'),
    'version', atlas_private.product_identity_constants()->>'version');
$function$;

-- Hand the recognition bodies to the definer role. It needs CREATE on the
-- schema only for the ownership change; it is revoked right after.
grant create on schema atlas_private to atlas_recognition_definer;
alter function atlas_private.recognition_resolve_codes(jsonb, uuid, text) owner to atlas_recognition_definer;
alter function atlas_private.recognition_candidate_features(jsonb, integer, uuid, text) owner to atlas_recognition_definer;
alter function atlas_private.recognition_register_media(jsonb, uuid, text) owner to atlas_recognition_definer;
alter function atlas_private.recognition_record(jsonb, uuid, text, text) owner to atlas_recognition_definer;
revoke create on schema atlas_private from atlas_recognition_definer;

-- atlas_private functions are service-internal. PUBLIC loses execute (the
-- definer role must not reach writers through PUBLIC); service_role keeps it.
revoke execute on all functions in schema atlas_private from public;
grant execute on all functions in schema atlas_private to service_role;
alter default privileges for role postgres in schema atlas_private revoke execute on functions from public;
alter default privileges for role postgres in schema atlas_private grant execute on functions to service_role;

-- Read-only helpers the definer role calls.
do $s89_definer_execute$
declare
  function_row record;
begin
  for function_row in
    select p.oid::regprocedure as signature
    from pg_catalog.pg_proc p
    join pg_catalog.pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'atlas_private'
      and (p.proname like 'product\_%' or p.proname in (
        'catalog_duplicate_score', 'inventory_class_for_category', 'inventory_alias_is_product_evidence',
        'recognition_actor', 'recognition_item_payload', 'recognition_json_text_array'))
  loop
    execute format('grant execute on function %s to atlas_recognition_definer', function_row.signature);
  end loop;
end
$s89_definer_execute$;

do $s89_public_grants$
declare
  function_row record;
begin
  for function_row in
    select p.oid::regprocedure as signature
    from pg_catalog.pg_proc p
    join pg_catalog.pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname in (
      'atlas_recognition_resolve_codes', 'atlas_recognition_candidates', 'atlas_recognition_register_media',
      'atlas_recognition_record', 'atlas_product_identity')
  loop
    execute format('revoke all on function %s from public, anon, authenticated', function_row.signature);
    execute format('grant execute on function %s to service_role', function_row.signature);
  end loop;
end
$s89_public_grants$;

comment on function public.atlas_recognition_candidates(jsonb, integer, uuid, text) is
  'S89 service-role-only recognition retrieval. Runs as atlas_recognition_definer (read + recognition audit only). Never changes stock.';
comment on function public.atlas_recognition_record(jsonb, uuid, text, text) is
  'S89 service-role-only recognition audit write (requests, detections, candidates). Never changes stock, items, codes or aliases.';

notify pgrst, 'reload schema';
